<?php
namespace App\Http\Controllers;
use App\Models\Shop;use App\Models\DeviceCommission;use App\Models\PlatformSettlement;use App\Services\AuditService;use App\Services\SettlementService;use App\Services\SmsService;use Illuminate\Http\Request;
class PlatformCommissionController extends Controller{
 public function index(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canShop('commission.view'),403);$shops=Shop::query()->when(!$r->user()->isSuperAdmin(),fn($q)=>$q->whereKey($r->user()->shop_id))->withCount('devices')->withSum('commissions','commission_amount')->withSum('commissions','paid_amount')->withSum('commissions','outstanding_amount')->get();$commissions=DeviceCommission::with(['device.customer','shop'])->when(!$r->user()->isSuperAdmin(),fn($q)=>$q->where('shop_id',$r->user()->shop_id))->latest()->paginate(30);$settlements=PlatformSettlement::with(['shop','reversal'])->when(!$r->user()->isSuperAdmin(),fn($q)=>$q->where('shop_id',$r->user()->shop_id))->latest('payment_date')->limit(50)->get();return view('commissions.index',compact('shops','commissions','settlements'));}
 public function settlement(Request $r,SettlementService $service,SmsService $sms,AuditService $audit){abort_unless($r->user()->isSuperAdmin(),403);$d=$r->validate(['shop_id'=>['required','exists:shops,id'],'amount'=>['required','numeric','min:0.01'],'payment_date'=>['required','date'],'payment_method'=>['required','in:cash,bank_transfer,card,qr_payment,cheque,other'],'reference_number'=>['nullable'],'allocation_method'=>['required','in:oldest_first,manual,unallocated_credit'],'device_commission_id'=>['required_if:allocation_method,manual','nullable','exists:device_commissions,id'],'notes'=>['nullable'],'password'=>['required','current_password']]);$shop=Shop::findOrFail($d['shop_id']);$s=$service->record($shop,$d,$r->user());$audit->record('SETTLEMENT_RECEIVED','Platform settlement recorded',$r->user(),null,[],['shop_id'=>$shop->id,'settlement_number'=>$s->settlement_number,'amount'=>$s->amount]);if($shop->sms_enabled)$sms->send('platform_settlement',$shop->mobile,['shop_name'=>$shop->name,'payment_amount'=>number_format((float)$s->amount,2),'remaining_balance'=>number_format((float)$shop->commissions()->sum('outstanding_amount'),2),'commission_balance'=>number_format((float)$shop->commissions()->sum('outstanding_amount'),2),'receipt_number'=>$s->settlement_number,'reference'=>$s->reference_number?:$s->settlement_number],$shop->id,null,null,$r->user());return redirect()->route('commissions.index')->with('success',"Settlement {$s->settlement_number} recorded.");}
 public function reverse(Request $r,PlatformSettlement $settlement,SettlementService $service,AuditService $audit){abort_unless($r->user()->isSuperAdmin(),403);$d=$r->validate(['password'=>['required','current_password'],'reason'=>['required'],'confirmed'=>['accepted']]);$service->reverse($settlement->load('allocations'),$r->user(),$d['reason']);$audit->record('SETTLEMENT_REVERSED','Platform settlement reversed: '.$d['reason'],$r->user(),null,['settlement_number'=>$settlement->settlement_number,'amount'=>$settlement->amount],[]);return back()->with('success','Settlement reversed with an immutable reversal record.');}
}
